/**
 * SnakeGame.score — 计分与最高分持久化（架构契约 v1 §2.2）
 *
 * 公开 API（冻结，不得改名或改变语义）：
 *   createScoreStore({storageKey, read, write}) → store
 *   getHighScore(store) → number
 *   onFood(game, store) → number
 *   onGameOver(game, store) → void
 *   resetCurrent(game) → void
 *
 * 约定：
 * - 计分唯一入口为 onFood，每个食物 +10 分；分数只增不减；
 * - 分数与最高分均为「非负整数」口径；
 * - 非法存储值按 0 处理；
 * - localStorage 读写以 try/catch 降级为内存，失败静默、不抛出、不阻断游戏；
 * - 持久化内容仅为最高分整数，不写任何玩家个人信息（A9）；
 * - 写入发生在刷新最高分时与每局结束；读取发生在 createScoreStore（app.init 阶段）。
 */
(function (root) {
  'use strict';

  var SnakeGame = root.SnakeGame || (root.SnakeGame = {});

  var DEFAULT_STORAGE_KEY = 'snake-game.highScore.v1';
  var SCORE_PER_FOOD = 10;

  /** 是否为非负整数（number 口径）。 */
  function isNonNegativeInteger(value) {
    return typeof value === 'number' &&
      isFinite(value) &&
      value >= 0 &&
      Math.floor(value) === value;
  }

  /** 归一化为非负整数；null/undefined/小数/负数/非数字字符串等非法值一律按 0。 */
  function toNonNegativeInteger(value) {
    if (isNonNegativeInteger(value)) return value;
    if (typeof value === 'string') {
      var text = value.trim();
      if (/^\d+$/.test(text)) {
        var parsed = parseInt(text, 10);
        if (isNonNegativeInteger(parsed)) return parsed;
      }
    }
    return 0;
  }

  /** 存储值可能是字符串或数字，统一按非负整数归一化。 */
  function normalizeHighScore(raw) {
    return toNonNegativeInteger(raw);
  }

  /**
   * 默认读取：localStorage.getItem。
   * 访问被拒（如 file:// 策略/SecurityError）或不可用时返回 null，
   * 由调用方按 0 处理，实现内存降级。
   */
  function defaultRead(storageKey) {
    try {
      if (typeof root.localStorage === 'undefined' || !root.localStorage) return null;
      return root.localStorage.getItem(storageKey);
    } catch (error) {
      return null;
    }
  }

  /**
   * 默认写入：localStorage.setItem，仅写最高分整数。
   * 写入失败（配额/禁用/安全异常）静默返回 false，内存中的最高分仍然有效。
   */
  function defaultWrite(storageKey, value) {
    try {
      if (typeof root.localStorage === 'undefined' || !root.localStorage) return false;
      root.localStorage.setItem(storageKey, String(value));
      return true;
    } catch (error) {
      return false;
    }
  }

  /**
   * 创建计分存储。默认键 snake-game.highScore.v1，默认读写包装 localStorage
   * 并以 try/catch 降级为内存；创建时读取一次持久化最高分（非法值按 0）。
   */
  function createScoreStore(options) {
    var opts = options || {};
    var storageKey = typeof opts.storageKey === 'string' && opts.storageKey.length > 0
      ? opts.storageKey
      : DEFAULT_STORAGE_KEY;
